SELECT status, COUNT(*) AS order_count
FROM orders
GROUP BY status;

SELECT name, price_minor / 100.0 AS list_price_dollars
FROM products
WHERE price_minor > 10000;

SELECT name, country
FROM customers
WHERE RTRIM(name) LIKE '% Walsh';

SELECT name
FROM products
WHERE price_minor = (SELECT MIN(price_minor) FROM products);

SELECT country AS country_code, COUNT(*) AS customer_count
FROM customers
GROUP BY country;

SELECT COALESCE(SUM((p.price_minor - oi.unit_price_minor) * oi.quantity), 0) / 100.0 AS total_discount_dollars
FROM order_items AS oi
JOIN products AS p ON p.id = oi.product_id;

SELECT ROUND(100.0 * AVG(
    CASE WHEN EXISTS (
        SELECT 1
        FROM refunds AS r
        WHERE r.order_id = o.id
          AND r.amount_minor > 0
    ) THEN 1 ELSE 0 END
), 2) AS refunded_percentage
FROM orders AS o
WHERE o.delivered_at IS NOT NULL;

SELECT COALESCE(SUM(
    o.shipping_minor + COALESCE((
        SELECT SUM(oi.quantity * oi.unit_price_minor)
        FROM order_items AS oi
        WHERE oi.order_id = o.id
    ), 0)
), 0) / 100.0 AS total_charge_dollars
FROM orders AS o
WHERE o.status = 'pending';

